<span class="line"><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">        WHEN</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 2</span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;"> THEN</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> 值2</span></span>
